340→// NewFactoryAIDroidRunner creates a new Factory AI Droid runner with the given config.
341→func NewFactoryAIDroidRunner(config AgentRunnerConfig) *FactoryAIDroidRunner {
342→	model := config.Model
343→	if model == "" {
344→		model = os.Getenv("E2E_DROID_MODEL")
345→		// No default model — use droid's built-in default if not specified
346→	}
