389→func (r *FactoryAIDroidRunner) RunPromptWithTools(ctx context.Context, workDir string, prompt string, tools []string) (*AgentResult, error) {
390→	args := []string{
391→		"exec",
392→		"--cwd", workDir,
393→		"--auto", r.AutoLevel,
394→		"-o", "text",
395→	}
396→
397→	// Droid uses its own permission system (.factory/settings.json), not --enabled-tools.
398→	// E2E tests pass Claude-specific tool names that Droid doesn't recognize.
399→
400→	if r.Model != "" {
401→		args = append(args, "-m", r.Model)
402→	}
403→
404→	args = append(args, prompt)
405→
406→	ctx, cancel := context.WithTimeout(ctx, r.Timeout)
407→	defer cancel()
408→
409→	//nolint:gosec // args are constructed from trusted config, not user input
410→	cmd := exec.CommandContext(ctx, "droid", args...)
411→	cmd.Dir = workDir
412→
413→	var stdout, stderr bytes.Buffer
414→	cmd.Stdout = &stdout
415→	cmd.Stderr = &stderr
416→
417→	start := time.Now()
418→	err := cmd.Run()
419→	duration := time.Since(start)
420→
421→	result := &AgentResult{
422→		Stdout:   stdout.String(),
423→		Stderr:   stderr.String(),
424→		Duration: duration,
425→	}
426→
427→	if err != nil {
428→		exitErr := &exec.ExitError{}
429→		if errors.As(err, &exitErr) {
430→			result.ExitCode = exitErr.ExitCode()
431→		} else {
432→			result.ExitCode = -1
433→		}
434→		//nolint:wrapcheck // error is from exec.Run, caller can check ExitCode in result
435→		return result, err
436→	}
437→
438→	result.ExitCode = 0
439→	return result, nil
440→}
