	})
	if err != nil {
		t.Fatalf("ReadSession() error = %v", err)
	}

	// Write to new location
	session.SessionRef = restoredPath
	if err := ag.WriteSession(session); err != nil {
		t.Fatalf("WriteSession() error = %v", err)
