	restored, err := os.ReadFile(restoredPath)
	if err != nil {
		t.Fatalf("failed to read restored: %v", err)
	}
	if string(restored) != content {
		t.Errorf("round-trip mismatch:\n got: %q\nwant: %q", string(restored), content)
	}
}

