	// Extract data directly from live transcript.
	transcriptPath := state.TranscriptPath
	// Dynamic fallback: if no live transcript path was stored in session state,
	// compute it from the agent type and repo path. This handles agents like
	// Factory AI Droid where transcript_path may not be set in all hooks.
	if transcriptPath == "" {
